gh_lore_zero_mana_notice.script:
const mana = check({type:'player-resource',resource:'Mana'}) || {};
const health = check({type:'player-resource',resource:'Health'}) || {};
const zero = Object.keys(mana).filter(n => mana[n] === 0 && (health[n] === undefined || health[n] > 0)).sort();
const old = storage.ghLoreZeroManaNames || [];
const fresh = zero.filter(n => old.indexOf(n) < 0);
storage.ghLoreZeroManaNames = zero;
if (!fresh.length) {
  skip = true;
} else {
  effects.push({type:'story',instruction:'Zero usable Mana alone leaves these living casters conscious: '+fresh.join(', ').slice(0,200)+'. Preserve any separately established unconsciousness or injury. Ordinary casting normally fizzles; a deliberately forced final spell requires an exceptionally difficult authoritative check and can cause migraines. Never spend vital mana, deduct Health as an automatic mana payment, invent a successful cast, or treat zero as soul shock.'});
}

