gh_portal_command_router.script:
// This router handles explicit solo commands in planning. Flexible/multiplayer
// wording remains with the gated semantic routers and the same per-tick lock.
const tick=check({type:'game-tick'});
const players=check({type:'player-level'})||{};
const raw=check({type:'action-text'});
const inputs=Array.isArray(raw)?raw:[raw];
let text=inputs.length===1&&typeof inputs[0]==='string'?inputs[0].trim().replace(/\s+/g,' ').toLowerCase():'';
// Leading quoted speech is not the action. Only inspect its explicit trailing
// physical clause; a quoted command by itself remains speech and cannot move.
const spokenPrefix=text.match(/^(?:"[^"]*"|“[^”]*”)\s+(.+)$/);
if(spokenPrefix)text=spokenPrefix[1];
const trailingSpeech=text.match(/^(.+?[.!]?)\s+(?:"[^"]*"|“[^”]*”)$/);
if(trailingSpeech)text=trailingSpeech[1].trim().replace(/[.!]$/,'');
const loc=check({type:'party-location'}),area=check({type:'party-area'});
const room=loc==='Evertree Base'&&area==='Evertree Base - Portal Room';
const dr=loc==='Drakenspire Portals';
const av=loc==='Cloudbloom Landing';
const sw=loc==='Silken Portal Room'&&check({type:'read-boolean',key:'gh_spider_entered'});
const home='(?:glowhaven|gloomhaven|evertree(?: base)?|the evertree portal room)';
const prefix='^(?:i )?(?:then )?(?:turn back and )?';
const finish='(?: again| once more)?[.!]?$';
let route='';
// 'Test the portal' is a single passage through the named route, not a free
// round-trip, another test, or an inspection of the frame without crossing.
if(room){
 const outbound=new RegExp(prefix+'(?:enter|cross|test|try|step through|walk through|go through|travel through|head through|head to|go to) (?:the |this )?(?:(?:portal|arch|gate) (?:to|for) )?((?:drakenspire|dragonspire)(?: mountains)?|asterveil(?: sky archipelago)?|silver web|silken descent)(?: (?:portal|arch|gate))?'+finish);
 const m=text.match(outbound);
 if(m)route=/^(?:drakenspire|dragonspire)/.test(m[1])?'drakenspire':m[1].startsWith('asterveil')?'asterveil':'silver';
 const using=new RegExp(prefix+'use (?:my |the )?(drakenspire|asterveil|silver web)(?: portal)? key(?: to (?:travel|go|cross)(?: (?:to|through) (?:the )?(?:portal|arch))?)?'+finish);
 const use=text.match(using);
 if(use)route=use[1]==='drakenspire'?'drakenspire':use[1]==='asterveil'?'asterveil':'silver';
 if(!route&&spokenPrefix&&/^(?:i )?(?:then )?(?:head|go|step|walk) in[.!]?$/.test(text)){
  const speech=spokenPrefix[0].slice(0,spokenPrefix[0].length-spokenPrefix[1].length);
  const choices=speech.match(/\b(?:drakenspire|dragonspire|asterveil)\b/g)||[];
  if(new Set(choices).size===1)route=choices[0]==='asterveil'?'asterveil':'drakenspire';
 }
}else if(dr||av||sw){
 const enter=new RegExp(prefix+'(?:enter|cross|step through|walk through|go through)(?: (?:the|this|that))?(?: return)?(?: (?:portal|arch|gate))?(?: (?:back )?to '+home+')?'+finish);
 const back=new RegExp(prefix+'(?:head|go|return|travel|walk)(?: back)? to '+home+finish);
 const via=new RegExp('^(?:i )?(?:then )?(?:turn back|head back|return|go back)(?: to| through| via) (?:the )?(?:return )?(?:portal|arch|gate)(?: (?:back )?to '+home+')'+finish);
 const key=new RegExp(prefix+'use (?:my |the )?(?:glowhaven|gloomhaven)(?: portal)?(?: return)? key(?: to return(?: to '+home+')?)?'+finish);
 const fixedArch=/^(?:i )?(?:then )?(?:enter|cross|step through|walk through|go through) (?:the |this |that )?(?:return )?(?:portal|arch|gate)(?: (?:back )?to [^.!?]+)?[.!]?$/.test(text);
 const bareCross=!/portal|arch|gate|glowhaven|gloomhaven|evertree/.test(text)&&enter.test(text);
 const bareAllowed=sw||/ - (?:Portal Room|Arrival Gate|Return Gate)$/.test(area);
 if((!bareCross||bareAllowed)&&(fixedArch||enter.test(text)||back.test(text)||via.test(text)||(key.test(text)&&check({type:'player-item',item:'Glowhaven Portal Key',operator:'greaterThan',value:0}))))route='home';
}
if(Object.keys(players).length!==1||!route||storage.ghPortalTransitTick===tick){skip=true;}else{
 const key=route==='drakenspire'?'Drakenspire Portal Key':route==='asterveil'?'Asterveil Portal Key':'Silver Web Portal Key';
 const allowed=route==='home'||(check({type:'player-item',item:key,operator:'greaterThan',value:0})&&(route!=='silver'||check({type:'read-boolean',key:'gh_silver_key_unlocked'})));
 if(!allowed){skip=true;}else{
  effects.length=0;
  const movement=(place,subarea)=>{
   effects.push({type:'party-location',operator:'set',value:place});
   effects.push({type:'party-area',operator:'set',value:subarea});
   effects.push({type:'npc-placement',npc:'allPartyNPCs',operation:'moveTo',location:place,area:subarea});
  };
  const tell=instruction=>effects.push({type:'story',instruction});
  const reveal=entity=>effects.push({type:'known-entity',entity,operator:'set',value:true});
  if((route==='drakenspire'||route==='asterveil')&&Object.values(players).some(level=>level>=20)&&!check({type:'read-boolean',key:'gh_spider_entered'})){
   storage.gh_spider_entered=true;storage.gh_exam_postponed=true;storage.gh_evertree_transited=true;
   storage.ghSpiderIncident={tick,intendedDestination:route==='drakenspire'?'Drakenspire Mountains':'Asterveil Sky Archipelago',key,players:Object.keys(players),companions:Object.keys(check({type:'npc-in-party',npc:'anyPartyNPC'})||{})};
   effects.push(...[{"type":"known-entity","entity":"The Silken Descent","operator":"set","value":true},{"type":"known-entity","entity":"Silken Chasm","operator":"set","value":true},{"type":"known-entity","entity":"Silken Portal Room","operator":"set","value":true},{"type":"party-location","operator":"set","value":"Silken Portal Room"},{"type":"party-area","operator":"set","value":"Silken Portal Room - Return Arch"},{"type":"npc-placement","npc":"allPartyNPCs","operation":"moveTo","location":"Silken Portal Room","area":"Silken Portal Room - Return Arch"},{"type":"story","instruction":"Interrupt the apparently normal crossing now: silver strands shear across the expected view and the actual party arrives together inside the ruined Silken Portal Room. Preserve companions and possessions. A silver-threaded key visibly condenses as the room is discovered; its one-time item effect records it. The stable return arch clearly leads home and is immediately usable without a key, descent or battle. Stop at arrival. No official predicted this event; do not descend or return for the player."}]);
  }else if(route==='home'){
   movement('Evertree Base','Evertree Base - Portal Room');
   if(sw){storage.gh_spider_returned=true;storage.ghSpiderFirstReturn=storage.ghSpiderFirstReturn||{tick,scene:'Actual first return from the anomalous room.'};}
   tell('The party actually returns to Evertree Base - Portal Room in Glowhaven. Preserve all belongings and the reusable silver key discovered on arrival. This is one completed return, not a matron victory, expedition credit or another outward crossing. The sole Glowhaven portal hub is this exact location and area. Do not offer another landing, academy portal or destination choice, and do not walk out of the hub for the player.');
  }else{
   const place=route==='drakenspire'?'Drakenspire Portals':route==='asterveil'?'Cloudbloom Landing':'Silken Portal Room';
   const subarea=route==='drakenspire'?'Drakenspire - Portal Room':route==='asterveil'?'Cloudbloom Landing - Portal Room':'Silken Portal Room - Return Arch';
   if(route==='drakenspire'){reveal('Drakenspire Mountains');reveal('Drakenspire Highlands');reveal(place);}
   if(route==='asterveil'){reveal('Asterveil Sky Archipelago');reveal('Cloudbloom Reaches');reveal(place);}
   movement(place,subarea);
   if(route!=='silver')storage.gh_evertree_transited=true;
   tell('The party actually arrives at '+subarea+'. This is one crossing. Describe the real enclosed destination Portal Room and its own local style, or the existing anomalous threshold for the silver route. Stop here. Testing the route does not choose to walk back, leave this room, meet distant people or complete an inspection.');
  }
  storage.ghPortalTransitTick=tick;
  storage.ghLastPortalTransit={tick,route,fromLocation:loc,fromArea:area,command:text};
 }
}

