gh_ai_local_reference_guard.script:
const tick=check({type:'game-tick'});
const raw=check({type:'action-text'});
const actions=(Array.isArray(raw)?raw:[raw]).filter(x=>typeof x==='string');
// Strip spoken quotations; a lexical cue is a reminder filter, not intent detection.
const active=actions.map(x=>x.replace(/"[^"\n]*"|“[^”\n]*”|`[^`\n]*`/g,' ').trim());
const cue=new RegExp("\\b(?:go|head|enter|return|cross|follow|explor\\w*|scout\\w*|flee\\w*|chas\\w*|travel|leave|step)\\b",'i');
const relevant=active.some(x=>cue.test(x)&&!/^\s*(?:what|how|why|could|would|should|if|suppose|imagine)\b/i.test(x)&&!/[?]\s*$/.test(x));
const seen=storage.gh_ai_notice_ticks||{};
if(!relevant||seen["gh_ai_local_reference_guard"]===tick){skip=true;}else{
 seen["gh_ai_local_reference_guard"]=tick;storage.gh_ai_notice_ticks=seen;
}

