 const pool=qualified.filter(j=>j.recommendedLevel<=entryLevel+(entryLevel<10?2:5));
 const cursor=Number(storage.q20_board_cursor)||0;
 let picked=named?[named]:[];
 for(let i=0;i<pool.length&&picked.length<2;i++){const j=pool[(cursor+i)%pool.length];if(!picked.includes(j))picked.push(j);}
 storage.q20_board_cursor=cursor+2;
 for(const j of picked){if(j.slug){storage['q20_offered_'+j.slug]=true;storage['q20_offer_tick_'+j.slug]=n;}if(check({type:'quest-status',questId:j.title})!=='completed')effects.push({type:'quest-init',operator:'set',value:j.title});}
 effects.push({type:'story',instruction:picked.length?'Present only these eligible choices with their real short premises, scope and full posted rewards: '+picked.map(j=>j.title+' (recommended level '+j.recommendedLevel+'+)').join('; ')+'. A concluded recurring contract needs fresh terms and actual new work, never a respawned old problem. If a specifically requested job exceeds the experience of this party, explain its actual danger before any acceptance; the named request only opens the offer. Reading a notice does not accept it. Other higher-tier work may be mentioned as locked, without a playable offer. No money, credit or portal permission is granted.':'No fresh authored posting is being selected now. Preserve accepted jobs and completed outcomes. Offer at most a couple of distinct suitable generated commissions or ordinary guild company when wanted, using actual badge, permission and beginner power rules; do not substitute a high-level fight or reopen old personal crises.'});
}

q20_academic_clock.script:
const n=Number(check({type:'game-tick'}))||0;
const status=q=>check({type:'quest-status',questId:q});
const theory=['Phoenix Wing: A Spell of Your Own','Gryffin Tail: A Spell of Your Own','Dragon Hoard: A Spell of Your Own','Hydra Head: A Spell of Your Own'];
const familiars=['Phoenix Wing: The Familiar Examination','Gryffin Tail: The Familiar Examination','Dragon Hoard: The Familiar Examination','Hydra Head: The Familiar Examination'];
const theses=['Phoenix Wing: One Question Worth Answering','Gryffin Tail: One Question Worth Answering','Dragon Hoard: One Question Worth Answering','Hydra Head: One Question Worth Answering'];
let phase=Number(storage.q20_academic_phase)||0;
const done=phase===0?theory.some(q=>status(q)==='completed'):
 phase===1?familiars.some(q=>status(q)==='completed'):
 phase===2?status('Four Academies, One Festival')==='completed':
 phase===3?!!storage.q20_expedition_recognized:
 phase===4?!!storage.q20_thesis_done:
 phase===5?status('What We Bring to the Next Morning')==='completed':false;
if(done&&phase<6){
 phase++;storage.q20_academic_phase=phase;
 storage.q20_last_major_tick=n;storage.q20_academic_activities=0;
 storage.q20_notice_sent=false;storage.q20_requested_advance=false;
}
const active=theory.some(q=>['accepted','completed'].includes(status(q)))||phase>0;
storage.q20_academic_active=active;
const gaps=[0,12,20,18,24,10],activities=[0,2,3,2,3,1];
const ready=phase<6&&(phase===0||storage.q20_requested_advance===true||
 (n-Number(storage.q20_last_major_tick||0)>=gaps[phase]&&Number(storage.q20_academic_activities||0)>=activities[phase]));
storage.q20_next_major_ready=!!ready;
for(let i=0;i<6;i++)storage['q20_major_eligible_'+i]=i===phase&&ready&&!(i===4&&storage.q20_thesis_done);
storage.q20_activity_window=active&&phase>0&&phase<6&&!ready&&n-Number(storage.q20_last_activity_tick||-100)>=4;
storage.q20_can_advance=active&&phase>0&&phase<6&&!ready;
let rank=0;
for(const [i,b]of ['Bronze','Silver','Gold','Platinum'].entries()){
 const held=check({type:'player-item',item:'Guild Badge: '+b})||{};
 if(Object.values(held).some(v=>v>0))rank=Math.max(rank,i+1);
}
storage.q20_guild_rank=rank;
for(let i=1;i<=4;i++)storage['q20_badge_rank_'+i]=rank>=i;

