av21_orivelle_circuit.script:
// A four-day circuit. Native NPC placement, not a player travel command.
const npc = 'Orivelle';
const health = check({type:'npc-health',npc});
const locked = storage.av21_orivelle_roaming_paused === true;
if (locked || (typeof health === 'number' && health <= 0) ||
    check({type:'npc-in-party',npc}) === true ||
    check({type:'npc-in-combat',npc}) === true ||
    check({type:'npc-in-scene',npc}) === true) {
  skip = true;
} else {
  const dayValue = Number(check({type:'day'}));
  const day = Number.isFinite(dayValue) && dayValue >= 1 ? Math.floor(dayValue) : 1;
  const route = [
    ['Mythwing Meadows','Mythwing Meadows - Return Hide'],
    ['Rimeglass Crown','Rimeglass Crown - Summit Saddle'],
    ['Mirrorwater Basin','Mirrorwater Basin - Rim Watch'],
    ['Prismbloom Basin','Prismbloom Basin - Mineral Shore']
  ];
  const index = (day - 1) % route.length;
  const destination = route[index];
  const here = check({type:'npc-location',npc});
  const area = check({type:'npc-area',npc});
  if (storage.av21_orivelle_route_day === day ||
      (here === destination[0] && area === destination[1])) {
    storage.av21_orivelle_route_day = day;
    skip = true;
  } else {
    effects.push({type:'npc-placement',npc,operation:'moveTo',location:destination[0],area:destination[1]});
    storage.av21_orivelle_route_day = day;
    storage.av21_orivelle_route_index = index;
  }
}

gh_daily_resource_recovery.script:
const day = check({type:'day'});
