if (!Number.isFinite(day) || day < 1) {
  skip = true;
} else if (!Number.isFinite(previous)) {
  storage.ghRecoveryLastDay = day;
  skip = true;
} else if (day <= previous) {
  skip = true;
} else {
  storage.ghRecoveryLastDay = day;
  effects.push({type:'story',instruction:'The actual party day counter has advanced. This is the one daily normal-recovery cue: restore Mana and Stamina to each living player character actual current maximum through the supported resource update, unless a completed rest or another supplied update already filled it for this transition. Do not restore either resource again on later turns of this day. This is resource recovery, not healing, resurrection, removal of soul shock, forced travel, or permission to choose the player activities.'});
}

