 if(custody&&role==='prisoner'){
  if(!Number.isFinite(storage.cp_entry_tick)){
   storage.cp_entry_tick=tick;storage.cp_last_prison_tick=tick;storage.cp_prison_count=0;
  }else if(tick>storage.cp_entry_tick&&storage.cp_last_prison_tick!==tick){
   storage.cp_prison_count=(Number(storage.cp_prison_count)||0)+1;storage.cp_last_prison_tick=tick;
  }
  if(storage.cp_prison_count>=15){
storage.gh_in_custody=false; storage.gh_prison_role='';
storage.gh_prison_wanted=false; storage.gh_prison_order=false;
storage.gh_prison_departed=true; storage.cp_pending=false;
