storage.cp_last_prison_tick=null; storage.cp_release_tick=tick;
effects.push({type:'party-location',operator:'set',value:'City Guard Headquarters'},
 {type:'party-area',operator:'set',value:'City Guard Headquarters - Public Entry'},
 {type:'npc-placement',npc:'allPartyNPCs',operation:'moveTo',location:'City Guard Headquarters',area:'City Guard Headquarters - Public Entry'},
 {type:'story',instruction:'After some time, the short custodial term ends. You are released and returned to the public entrance of Glowhaven City Guard Headquarters. Preserve actual belongings, injuries and established companions; do not grant money or replacement equipment. This automatic wanted case is closed. Continue from the actual return location without demanding a new application or another sentence for the same incident.'});
  }
 }
}else{
 if(!custody){storage.cp_entry_tick=null;storage.cp_last_prison_tick=null;storage.cp_prison_count=0;}
 if(storage.cp_pending===true&&tick>=Number(storage.cp_due_tick)){
  storage.cp_pending=false;
  if(held<=0){effects.push({type:'item-add',item:'Wanted Poster',quantity:1,target:'allPlayers'},
   {type:'story',instruction:'A creased wanted poster has found its way among your belongings. Your own face is printed on it. Let the discovery happen naturally; do not expose flags, trigger logic or an invisible police meter.'});}
 }
}
// Possession is the only automatic-enforcement switch. No reissue on discard.
if(held<=0&&!storage.cp_pending){storage.cp_next_demand_tick=0;}
}

