ad34_scene_dispatch.script:
const jobs = [{"title": "Borrowed After the Applause", "source": "Adoha Aonuma", "location": "Four Sages Bazaar", "level": 1}, {"title": "A Stable Fit for Old Bones", "source": "Ragnar Leonhart", "location": "Whitepass Caravan Lodge", "level": 1}, {"title": "Three Rhymes Behind", "source": "Karia Morino", "location": "Crooked Tankard", "level": 1}, {"title": "The Map Has Your Footprints", "source": "Renpei Sugita", "location": "Adventurer's Guild - Glowhaven Branch", "level": 6}, {"title": "A Handle Worth Keeping", "source": "Tetsuya Kanamori", "location": "Adventurer's Guild - Glowhaven Branch", "level": 4}, {"title": "The Quiet Room", "source": "Nae Komorida", "location": "Willowbend Residential District", "level": 1}, {"title": "Prison: A Dry Line Tomorrow", "source": "Masaru Hasebe", "location": "Prison Work Yard", "level": 1}, {"title": "Prison: The Book Returns", "source": "Akira Oritsu", "location": "Prison Records Office", "level": 1}];
const location = check({type:'party-location'});
const actions = check({type:'action-text'});
const text = (Array.isArray(actions) ? actions : [actions]).join(' ');
const levels = Object.values(check({type:'player-level'}) || {}).filter(x=>typeof x==='number' && x>0);
const minLevel = levels.length ? Math.min(...levels) : 1;
storage.ad34_solo = levels.length === 1;
storage.ad34_offer_target = '';
const propertyWords = /\b(rent|lease|purchase|buy|bought|rented|own|ownership|deed|lodging|room|workshop|house|property|key)\b/i.test(text);
storage.ad34_property_interest = propertyWords;
const candidates = jobs.filter(j => j.location === location &&
  check({type:'quest-status',questId:j.title}) === 'hidden' &&
  check({type:'npc-in-scene',npc:j.source}) === true &&
  minLevel + 2 >= j.level);
const explicit = candidates.find(j=>text.toLowerCase().includes(j.title.toLowerCase()));
const addressed = candidates.find(j=>text.toLowerCase().includes(j.source.toLowerCase()) || text.toLowerCase().includes(j.source.split(' ')[0].toLowerCase()));
const recent = String(check({type:'story-text'}) || '');
const followup = /\b(yes|sure|okay|ok|accept|agree|terms|pay|payment|do that|i will|i'll)\b/i.test(text) &&
  candidates.find(j=>recent.toLowerCase().includes(j.title.toLowerCase()));
if (/\b(job|work|help|request|commission|task|posting|offer|problem|repair)\b/i.test(text) || explicit || followup) {
  const choice = explicit || followup || addressed || (candidates.length === 1 ? candidates[0] : null);
  if (choice) storage.ad34_offer_target = choice.title;
}
// Older Canopy offers share a venue. Expose only the current conversation's job.
const legacy = [{"title": "A Road Made of Air: The Far End", "source": "Sakuya Tomonari", "words": "crossing|route|tether|road made"}, {"title": "The Hunt That Looks Back: A Shape in the Wake", "source": "Sakuya Tomonari", "words": "hunt|predator|shape.*wake"}, {"title": "First Bloom, Last Rehearsal", "source": "Sakuya Tomonari", "words": "bloom|rehearsal|celebration"}, {"title": "A Voice Below the Roots", "source": "Sakuya Tomonari", "words": "roots|voice|hum"}, {"title": "What the Manta Leaves", "source": "Sakuya Tomonari", "words": "manta|shed|comb"}, {"title": "The Room Below the Ring", "source": "Kureha Kazahana", "words": "orrery|drown|ring"}, {"title": "An Impossible Shade of Green", "source": "Kureha Kazahana", "words": "shade|green|pigment"}, {"title": "Two Teams, One Clean Sample", "source": "Kureha Kazahana", "words": "rival|teams|clean sample"}];
storage.ad34_legacy_offer = '';
if (location === 'Asterveil Canopy') {
  const available = legacy.filter(j=>check({type:'npc-in-scene',npc:j.source}) === true &&
    !['accepted','completed'].includes(check({type:'quest-status',questId:j.title})));
  const named = available.find(j=>text.toLowerCase().includes(j.title.toLowerCase())) ||
    available.find(j=>recent.toLowerCase().includes(j.title.toLowerCase()));
  const relevant = available.find(j=>new RegExp(j.words,'i').test(text));
  const chosen = named || relevant || (/\b(job|work|help|request|offer)\b/i.test(text) && available.length ? available[0] : null);
  if (chosen) storage.ad34_legacy_offer = chosen.title;
}

ad34_quest_repair.script:
const raw = check({type:'action-text'});
const inputs = Array.isArray(raw) ? raw : [raw];
const seen = [];
for (const input of inputs) {
  // Match only the whole out-of-character command, never a quotation inside prose.
  const match = /^\s*quest done:\s*([^\r\n]+?)\s*$/i.exec(String(input || ''));
  if (!match) continue;
  const title = match[1];
  if (seen.includes(title)) continue;
  seen.push(title);
  const status = check({type:'quest-status',questId:title});
  if (status !== 'accepted') {
    effects.push({type:'story',instruction:'Out of character only: the quest-repair command found no accepted quest with the exact supplied name. Give one short correction note without quoting internal flags. Do not change a quest, item, reward or NPC memory, and continue the current scene.'});
  } else {
    effects.push({type:'quest-complete',questId:title});
    effects.push({type:'story',instruction:'The player used the out-of-character journal repair for '+title+'. Let its normal completion effects settle once. Continue the existing scene; NPCs did not hear a command and no fictional deed, forged evidence or extra payment is retroactively invented.'});
  }
  if (effects.length >= 8) break;
}
if (!effects.length) skip = true;

