const rnd=()=>{c.seed=((c.seed||1931)*1664525+1013904223)>>>0;return c.seed/4294967296;};
const available=x=>x.name!==c.entrant&&check({type:'npc-location',npc:x.name})===venue&&check({type:'npc-in-party',npc:x.name})!==true&&check({type:'npc-in-combat',npc:x.name})!==true&&!(typeof health(x.name)==='number'&&health(x.name)<=0);
const callNext=()=>{const m=current();if(!m)return;if(available({name:m.opponent})){effects.push({type:'known-entity',entity:m.opponent,operator:'set',value:true},{type:'npc-placement',npc:m.opponent,operation:'moveTo',location:venue,area:venue+' - Competitor Lounge'});}say('The next scheduled bout is '+m.label+': '+c.entrant+' versus '+m.opponent+' at '+m.arena+'. Announce it once and wait for explicit readiness. The entrant can watch, converse or rest while waiting. Another fighter\'s result never advances this entry or starts the called bout.');};
